import { BufferGeometry, BufferAttribute } from 'three';

/**
 * Build a Mobius strip as a custom BufferGeometry.
 *
 * Standard parameterization:
 *   p(u, v) = ((radius + v*cos(u/2))*cos(u),
 *              (radius + v*cos(u/2))*sin(u),
 *              v*sin(u/2))
 * with u in [0, 2PI], v in [-width/2, width/2].
 *
 * @param {{radius?: number, width?: number, segU?: number, segV?: number}} opts
 * @returns {import('three').BufferGeometry}
 */
export function mobiusGeometry({ radius = 3, width = 1, segU = 128, segV = 8 } = {}) {
  const geometry = new BufferGeometry();

  const cols = segU + 1; // u samples (seam duplicated at u=0 and u=2PI)
  const rows = segV + 1; // v samples

  const positions = new Float32Array(cols * rows * 3);

  let ptr = 0;
  for (let i = 0; i < cols; i++) {
    const u = (i / segU) * Math.PI * 2;
    const cosHalf = Math.cos(u / 2);
    const sinHalf = Math.sin(u / 2);
    const cosU = Math.cos(u);
    const sinU = Math.sin(u);

    for (let j = 0; j < rows; j++) {
      const v = -width / 2 + (j / segV) * width;

      positions[ptr++] = (radius + v * cosHalf) * cosU;
      positions[ptr++] = (radius + v * cosHalf) * sinU;
      positions[ptr++] = v * sinHalf;
    }
  }

  // Two triangles per quad; column-major indexing matching the position layout.
  const indices = new Uint32Array(segU * segV * 6);
  let idx = 0;
  for (let i = 0; i < segU; i++) {
    for (let j = 0; j < segV; j++) {
      const a = i * rows + j;       // (i, j)
      const b = (i + 1) * rows + j; // (i+1, j)
      const c = (i + 1) * rows + j + 1; // (i+1, j+1)
      const d = i * rows + j + 1;   // (i, j+1)

      indices[idx++] = a;
      indices[idx++] = b;
      indices[idx++] = d;

      indices[idx++] = b;
      indices[idx++] = c;
      indices[idx++] = d;
    }
  }

  geometry.setAttribute('position', new BufferAttribute(positions, 3));
  geometry.setIndex(new BufferAttribute(indices, 1));
  geometry.computeVertexNormals();

  return geometry;
}

/**
 * Basic stats about a strip geometry.
 *
 * @param {import('three').BufferGeometry} geo
 * @returns {{vertexCount: number, triangleCount: number, bbox: {min: number[], max: number[]}}}
 */
export function stripStats(geo) {
  const pos = geo.getAttribute('position');
  geo.computeBoundingBox();
  const bbox = geo.boundingBox;

  return {
    vertexCount: pos.count,
    triangleCount: geo.index ? geo.index.count / 3 : 0,
    bbox: {
      min: [bbox.min.x, bbox.min.y, bbox.min.z],
      max: [bbox.max.x, bbox.max.y, bbox.max.z],
    },
  };
}

