import { describe, it, expect } from 'vitest';
import { mobiusGeometry, stripStats } from '../src/mobius.js';

describe('mobiusGeometry', () => {
  it('has vertexCount (segU+1)*(segV+1)', () => {
    const params = [
      {},
      { radius: 5, width: 2 },
      { segU: 32, segV: 4 },
      { segU: 7, segV: 13, radius: 2, width: 0.5 },
    ];
    for (const opts of params) {
      const geo = mobiusGeometry(opts);
      const { segU = 128, segV = 8 } = opts;
      expect(geo.getAttribute('position').count).toBe((segU + 1) * (segV + 1));
      geo.dispose();
    }
  });

  it('has triangleCount segU*segV*2', () => {
    const params = [
      {},
      { segU: 16, segV: 3 },
      { segU: 64, segV: 10 },
    ];
    for (const opts of params) {
      const geo = mobiusGeometry(opts);
      const { segU = 128, segV = 8 } = opts;
      expect(geo.index.count / 3).toBe(segU * segV * 2);
      geo.dispose();
    }
  });

  it('identifies the seam: (u=0, v=+w/2) equals (u=2PI, v=-w/2) within 1e-6', () => {
    const width = 1;
    const segU = 128;
    const segV = 8;
    const geo = mobiusGeometry({ width, segU, segV });
    const pos = geo.getAttribute('position');
    const rows = segV + 1;

    // Column-major layout: index = i*rows + j, j=0 -> v=-w/2, j=segV -> v=+w/2
    const startEdge = pos.count - rows; // i = segU (u = 2PI)
    const a = (0 * rows + segV) * 3;          // u=0, v=+w/2
    const b = (startEdge + 0) * 3;            // u=2PI, v=-w/2

    expect(Math.abs(pos.array[a] - pos.array[b])).toBeLessThan(1e-6);
    expect(Math.abs(pos.array[a + 1] - pos.array[b + 1])).toBeLessThan(1e-6);
    expect(Math.abs(pos.array[a + 2] - pos.array[b + 2])).toBeLessThan(1e-6);
    geo.dispose();
  });

  it('has only finite positions', () => {
    const geo = mobiusGeometry({ radius: 3, width: 1, segU: 128, segV: 8 });
    const arr = geo.getAttribute('position').array;
    for (let k = 0; k < arr.length; k++) {
      expect(Number.isFinite(arr[k])).toBe(true);
    }
    geo.dispose();
  });

  it('bbox x and y extents are close to 2*(radius + width/2) within 1e-3', () => {
    const cases = [
      { radius: 3, width: 1 },
      { radius: 5, width: 2, segU: 256 },
      { radius: 1, width: 0.5 },
    ];
    for (const opts of cases) {
      const { radius, width } = opts;
      const geo = mobiusGeometry({ ...opts, segU: opts.segU ?? 512, segV: opts.segV ?? 8 });
      const stats = stripStats(geo);
      const expected = 2 * (radius + width / 2);
      const exX = stats.bbox.max[0] - stats.bbox.min[0];
      const exY = stats.bbox.max[1] - stats.bbox.min[1];
      expect(Math.abs(exX - expected)).toBeLessThan(1e-3);
      expect(Math.abs(exY - expected)).toBeLessThan(1e-3);
      geo.dispose();
    }
  });

  it('stripStats reports consistent numbers', () => {
    const geo = mobiusGeometry({ radius: 3, width: 1, segU: 20, segV: 5 });
    const stats = stripStats(geo);
    expect(stats.vertexCount).toBe(21 * 6);
    expect(stats.triangleCount).toBe(20 * 5 * 2);
    expect(stats.bbox.min.length).toBe(3);
    expect(stats.bbox.max.length).toBe(3);
    geo.dispose();
  });
});

