it('bbox x/y reach is the outer radius: 2*max(|min|,|max|) ~= 2*(radius + width/2) within 1e-3', () => {
  // Note: the raw (max-min) extent is NOT 2*(r+w/2): at u=PI the half-twist
  // gives cos(u/2)=0 so x=-r exactly, and the interior critical point only
  // reaches ~-(r + tiny). The strip's reach along each axis is the outer
  // radius r+w/2 (attained at u=0 / u=PI/2 etc.), which is what we verify.
  const cases = [
    { radius: 3, width: 1 },
    { radius: 5, width: 2, segU: 256 },
    { radius: 1, width: 0.5 },
  ];
  for (const opts of cases) {
    const { radius, width } = opts;
    const geo = mobiusGeometry({ ...opts, segU: opts.segU ?? 512, segV: opts.segV ?? 8 });
    const stats = stripStats(geo);
    const expected = 2 * (radius + width / 2);
    for (const axis of [0, 1]) {
      const reach = Math.max(
        Math.abs(stats.bbox.min[axis]),
        Math.abs(stats.bbox.max[axis])
      );
      expect(Math.abs(2 * reach - expected)).toBeLessThan(1e-3);
      // and the strip never pokes outside the outer-radius annulus:
      expect(reach).toBeLessThanOrEqual(radius + width / 2 + 1e-9);
    }
    geo.dispose();
  }
});

