    expect(stats.bbox.max[0]).toBeGreaterThan(radius); // extends past the core circle
    expect(Math.abs(stats.bbox.min[0])).toBeLessThanOrEqual(outer + 1e-9);
    expect(Math.abs(stats.bbox.min[1])).toBeLessThanOrEqual(outer + 1e-9);
    expect(Math.abs(stats.bbox.max[1])).toBeLessThanOrEqual(outer + 1e-9);
    geo.dispose();
  }
